import {getUserDetail, addUser, updateUser} from "@/api/terminal";
export default {
  data() {
    return {
      id: '',
      form: {
        terminal: "",
        name: "",
        userType: "",
        timeList: [],
        loginBeginTime: "",
        loginEndTime: "",
      },
      loading: true,
      isEdit: true,
      userTypeList:[{
        label: '管理员',
        value: '管理员'
      },{
        label: '普通用户',
        value: '普通用户'
      }],
      deviceStatusList:[{
        label: '1',
        value: '在线'
      },{
        label: '0',
        value: '离线'
      }],
      btnLoading: false,
      pickerOptions: {
          shortcuts: [{
            text: '最近一周',
            onClick(picker) {
              const end = new Date();
              const start = new Date();
              start.setTime(start.getTime() - 3600 * 1000 * 24 * 7);
              picker.$emit('pick', [start, end]);
            }
          }, {
            text: '最近一个月',
            onClick(picker) {
              const end = new Date();
              const start = new Date();
              start.setTime(start.getTime() - 3600 * 1000 * 24 * 30);
              picker.$emit('pick', [start, end]);
            }
          }, {
            text: '最近三个月',
            onClick(picker) {
              const end = new Date();
              const start = new Date();
              start.setTime(start.getTime() - 3600 * 1000 * 24 * 90);
              picker.$emit('pick', [start, end]);
            }
          }]
        },
    };
  },
  async mounted() {
    // 设置页面元素高度
    this.setPageContentHeight()
    this.id = null;
    //获取参数 判断是否是新增还是修改
    const params = this.$route.query
    //params.id='1760851395719598082'
    this.id = params.id || '';
    if (params.id) {
      this.id = params.id;
      this.loadDetail(params.id);
      this.isEdit = true
    } else {
      //加载空数据
      this.beforeOpen();
      this.isEdit = true
    }
  },
  methods: {
    async handleSaveOK() {
      this.$refs.dataForm.validate(async (valid) => {
        if (valid) {
          this.btnLoading = true //按钮加载状态
          let saveRes = this.id ? await updateUser({
            ...this.form,
            loginBeginTime: this.form.timeList[0],
            loginEndTime: this.form.timeList[1],
          }) : await addUser({
            ...this.form,
            loginBeginTime: this.form.timeList[0],
            loginEndTime: this.form.timeList[1],
          })
          if (saveRes[0] != null) {
            this.btnLoading = false
            return
          }
          this.btnLoading = false
          this.$message({
            type: "success",
            message: "操作成功!"
          });
          this.handleReset();
        }
      })
    },
    handleReset() {
      //返回
      this.$closePage('/device/devApply');
    },
    beforeOpen() {
      getEmpty().then(res => {
        this.form = res.data;
        this.form.id = null;
        this.$forceUpdate()
      });
    },
    loadDetail(id) {
      getUserDetail(id).then(res => {
        this.form = res.data
        console.log('this.form',this.form)
        this.form.timeList = [res.data.loginBeginTime,res.data.loginEndTime]
        this.form.status = res.data.status == 1 ? '在线' : '离线'
        this.$refs.dataForm.$forceUpdate()
        this.$forceUpdate()
      });
    },
  }
};
